WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_eng_t_first'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '谁先完工', 'kp-eng-t-first', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "谁先完工比较"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "多个独立项目齐头并进，比拼完工时间。核心是计算每个人的 T = W / P。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "甲修 A 路，乙修 B 路。两人同时开工，问谁先完工，先完工几天？"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这实际上是两道平行的极简工程题，各自算各自的，互不干扰。"}]}, {"type": "katexBlock", "attrs": {"content": "T_甲 = \\frac{W_A}{P_甲} \\quad ; \\quad T_乙 = \\frac{W_B}{P_乙} \\quad \\Rightarrow \\quad \\text{比较 } T_甲 \\text{ 和 } T_乙"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出 A 项目的总量和甲的效率] --> B[算出 T甲]\nC[列出 B 项目的总量和乙的效率] --> D[算出 T乙]\nB --> E{比较 T甲 和 T乙}\nD --> E\nE --> F[较小的 T 是先完工的, 两者之差为先完工的天数]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 甲负责 300 件任务，每天做 15 件；乙负责 400 件任务，每天做 25 件。两人同时开工，谁先做完？先做完几天？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算甲：T甲 = 300 ÷ 15 = 20 天。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算乙：T乙 = 400 ÷ 25 = 16 天。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "比较：16 < 20。所以乙先做完。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算差值：20 - 16 = 4 天。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "结论：乙先完工，提前了 4 天。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "被互帮互助迷惑：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "题目往往会加个尾巴：“先做完的人去帮另一个人做”。此时一定要弄清楚！在问“谁先完工”这个时间点时，还没有发生互帮互助！直接按他们单干的速度去算第一阶段的结束点。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这是复合工程题的第一问。迅速准确算出两个独立完工时间，是解决后续“帮工”问题的基础。"}]}]}$$ AS jsonb), NULL, '谁先完工的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "谁先完工"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_t_first", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
